def check_solution(n):
    if n <= 0:
        return False

    # Calculate n_12 = n^12. Since we only need tau(n^12), we don't need to calculate the massive number n^12.
    # If n = p1^a1 * p2^a2 * ..., then n^12 = p1^(12*a1) * p2^(12*a2) * ...
    # tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...

    if n == 1:
        return True # 1 = tau(1)

    factors_n = prime_factorization(n)

    tau_n_12 = 1
    for p, a in factors_n.items():
        # The exponent of p in n^12 is 12 * a
        tau_n_12 *= (12 * a + 1)

    return n == tau_n_12

